recipes.code:
{
  "inputs": [
    {
      "id": "formio-api-key",
      "type": "promptString",
      "description": "Form.io project API key. Optional — when omitted the server uses a browser-based portal login flow to obtain a JWT.",
      "password": true
    }
  ],
  "servers": {
    "formio": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@formio/mcp@0.7.0"
      ],
      "env": {
        "FORMIO_PROJECT_URL": "<formio-project-url>",
        "FORMIO_BASE_URL": "<formio-base-url>",
        "FORMIO_API_KEY": "${input:formio-api-key}",
        "FORMIO_LOGIN_FORM": "<formio-login-form>",
        "FORMIO_INSECURE_TLS": "<formio-insecure-tls>"
      }
    }
  }
}
